// 冷态沿真实事实序复算：本人决定、实际Estate到岗、原LE工资及原钱包预约必须全部闭合。
#include "estate_employment_internal.hpp"
#include "../estate_title_history.hpp"
#include "../../commerce/private_shop_staff_exclusion.hpp"
#include "resident/domains/family/actor_age_read.hpp"
#include "resident/domains/family/actor_death_read.hpp"
#include <charconv>
namespace hanmo::resident {
namespace {
using namespace estate_employment_detail;
// ID必须来自同Common计数器，且头与载荷一一对应；不能仅凭任意前缀认来源。
bool serial(const CommonStore& c,const StableId& id,const StableId& prefix){if(id.rfind(prefix+":",0)!=0)return false;const auto text=id.substr(prefix.size()+1);Integer value=0;const auto parsed=std::from_chars(text.data(),text.data()+text.size(),value);return parsed.ec==std::errc{}&&parsed.ptr==text.data()+text.size()&&value>0&&value<c.state().next_instance_id&&text==std::to_string(value);}
Status meeting(const EstateEmploymentContext& x,const EstateEmploymentMeeting& m,const EstateEmploymentTerms& t,const EstateEmploymentPolicy& p,const EstateDefinition& estate,bool employer,bool declaration){
 const auto actor=declaration?(employer?t.worker_actor_id:t.employer_actor_id):(employer?t.employer_actor_id:t.worker_actor_id);const auto provider=actor==t.worker_actor_id?t.employer_actor_id:t.worker_actor_id;
 const auto dialogue=declaration?(employer?p.provider_offer_dialogue_id:p.provider_reply_dialogue_id):(employer?p.offer_dialogue_id:p.worker_dialogue_id);const auto node_id=declaration?(employer?p.provider_offer_node_id:p.provider_reply_node_id):(employer?p.offer_node_id:p.worker_node_id);
 if(m.actor_id!=actor||m.provider_actor_id!=provider||m.session_id.empty()||m.dialogue_id!=dialogue||m.node_id!=node_id||m.place_id!=estate.place_id||(m.node_kind!="say"&&m.node_kind!="choice"))return common_failure("InvalidEmploymentMeeting");
 if(!declaration)return m.speaker_actor_id.empty()?common_success():common_failure("UnexpectedEmploymentSpeaker");
 const DialogueNode* node=nullptr;for(const auto& d:x.interaction_catalog->dialogues)if(d.id==dialogue)for(const auto& n:d.nodes)if(n.id==node_id)node=&n;
 if(!node||node->kind!="say"||m.node_kind!="say"||m.speaker_actor_id!=provider||(node->speaker!="$provider"&&node->speaker!=provider))return common_failure("EmploymentProviderSourceMismatch");return common_success();
}
}
Status validate_estate_employment_original_sources(const EstateEmploymentContext& x){
 auto observed=observed_tick(x);if(!observed.ok)return {false,{},observed.error};auto policies=validate_catalog(x);if(!policies.ok)return policies;
 std::map<StableId,std::size_t> sequence;std::size_t ordinal=0;for(const auto& row:x.common.state().facts.rows())sequence[row.first]=++ordinal;
 auto header=[&](const StableId& id,const StableId& prefix,const StableId& kind,const StableId& domain){const auto* h=x.common.state().facts.find(id);return serial(x.common,id,prefix)&&h&&h->id==id&&h->kind==kind&&h->domain==domain;};
 auto before=[&](const StableId& a,const StableId& b){return sequence.count(a)&&sequence.count(b)&&sequence[a]<sequence[b];};
 std::set<StableId> decisions,services,obligations,all_due,all_payments;std::map<StableId,std::vector<std::pair<Integer,Integer>>> worker_periods;
 for(const auto& row:x.state.contracts.rows()){
  const auto& c=row.second;const auto& t=c.terms;const auto* p=x.catalog.policies.find(t.policy_id);const auto* e=x.estate_catalog.estates.find(t.estate_id);const auto* current=x.estates.estates.find(t.estate_id);const auto* rate=x.economy_catalog.rates.find(t.rate_profile);const auto* worker=x.common.actor(t.worker_actor_id);const auto* employer=x.common.actor(t.employer_actor_id);const auto* wallet=x.common.wallet(t.payer_wallet_id);const auto* payee=x.common.wallet(t.payee_wallet_id);
  if(row.first!=c.id||!header(c.id,"estate_employment","estate_employment_offered",estate_employment_module)||!p||!e||!current||!rate||!worker||!employer||worker->id==employer->id||!wallet||!payee||c.offered_tick<x.state.initialized_tick||c.offered_tick>x.common.tick())return common_failure("InvalidEmploymentOffer",row.first);
  Integer expiry=0;if(!add(c.offered_tick,p->offer_valid_ticks,expiry))return common_failure("EstateEmploymentTickOverflow",c.id);auto cap=reservation_cap(rate->numerator,rate->denominator,p->service_ticks);if(!cap.ok)return {false,{},cap.error};
  StableId original_employer=current->owner_actor_id;
  if(x.estate_titles){auto title=x.estate_titles->read_estate_title_before_source(t.estate_id,{estate_employment_module,"estate_employment_offered",c.id});if(!title.ok)return {false,{},title.error};if(title.value.legal_owner.kind!=Owner::Kind::actor||title.value.estate_id!=t.estate_id||title.value.wallet_id!=e->wallet_id||title.value.inventory_id!=e->inventory_id)return common_failure("EmploymentOriginalTitleMismatch",c.id);original_employer=title.value.legal_owner.id;auto now=x.estate_titles->read_current_estate_title(t.estate_id);if(!now.ok)return {false,{},now.error};if(now.value.wallet_id!=t.payer_wallet_id||!owner_equal(wallet->owner,now.value.legal_owner))return common_failure("EmploymentCurrentTitleProjectionMismatch",c.id);}
  EstateEmploymentTerms expected{p->id,p->estate_id,original_employer,worker->id,p->job,p->rate_profile,e->wallet_id,worker->wallet_id,rate->numerator,rate->denominator,p->service_ticks,expiry,cap.value};
  if(!same_terms(t,expected)||wallet->id==payee->id||(!x.estate_titles&&!owner_equal(wallet->owner,{Owner::Kind::actor,t.employer_actor_id,{}}))||!owner_equal(payee->owner,{Owner::Kind::actor,t.worker_actor_id,{}}))return common_failure("EmploymentTermsMismatch",c.id);
  auto source=meeting(x,c.offered_at,t,*p,*e,true,c.offer_from_provider);if(!source.ok)return source;
  const EstateEmploymentDecisionFact* accepted=nullptr;const EstateEmploymentDecisionFact* terminal=nullptr;
  for(const auto& event:x.state.decisions.rows())if(event.second.contract_id==c.id){const auto& d=event.second;if(event.first!=d.id||!header(d.id,"estate_employment_decision","estate_employment_decided",estate_employment_module)||!before(c.id,d.id)||d.tick<c.offered_tick||d.tick>observed.value||!decisions.insert(d.id).second)return common_failure("InvalidEmploymentDecision",event.first);
   if(d.decision=="accept"){
    if(!d.death_fact_id.empty()||(d.provider_declared&&p->provider_reply_decision!="accept")||accepted||terminal||d.actor_id!=t.worker_actor_id||!d.meeting||!d.terminal_arrear_id.empty()||d.tick>=t.offer_expires_tick||d.tick>x.common.tick())return common_failure("InvalidEmploymentAcceptance",d.id);source=meeting(x,*d.meeting,t,*p,*e,false,d.provider_declared);if(!source.ok)return source;if(x.estate_titles){auto title=x.estate_titles->read_estate_title_before_source(t.estate_id,{estate_employment_module,"estate_employment_decided",d.id});if(!title.ok)return {false,{},title.error};if(title.value.wallet_id!=t.payer_wallet_id||!owner_equal(title.value.legal_owner,{Owner::Kind::actor,t.employer_actor_id,{}}))return common_failure("EmploymentAcceptanceTitleMismatch",d.id);}accepted=&d;
   }else{
    if(terminal)return common_failure("DuplicateEmploymentTermination",d.id);const bool worker_decision=d.decision=="decline"||d.decision=="leave";const bool owner_decision=d.decision=="withdraw"||d.decision=="dismiss";const bool elapsed=d.decision=="expired";const bool deceased=d.decision=="worker_dead"||d.decision=="employer_dead";
    if((!worker_decision&&!owner_decision&&!elapsed&&!deceased)||(worker_decision&&d.actor_id!=t.worker_actor_id)||(owner_decision&&d.actor_id!=t.employer_actor_id)||((elapsed||deceased)&&!d.actor_id.empty()))return common_failure("EmploymentDecisionActorMismatch",d.id);
    if(deceased){if(!x.life||d.death_fact_id.empty())return common_failure("EmploymentDeathHistoryRequired",d.id);auto death=read_actor_death_before_fact(x.common,*x.life,d.decision=="worker_dead"?t.worker_actor_id:t.employer_actor_id,d.tick,d.id);if(!death.ok)return {false,{},death.error};if(!death.value||death.value->death_fact_id!=d.death_fact_id)return common_failure("EmploymentDeathHistoryMismatch",d.id);}else if(!d.death_fact_id.empty())return common_failure("UnexpectedEmploymentDeathSource",d.id);
    if(d.decision=="decline"){if((d.provider_declared&&p->provider_reply_decision!="decline")||accepted||!d.meeting)return common_failure("InvalidEmploymentDecline",d.id);source=meeting(x,*d.meeting,t,*p,*e,false,d.provider_declared);if(!source.ok)return source;}else if(d.meeting||d.provider_declared)return common_failure("UnexpectedEmploymentMeeting",d.id);
    if((d.decision=="withdraw"&&accepted)||((d.decision=="leave"||d.decision=="dismiss")&&!accepted)||(accepted&&!before(accepted->id,d.id)))return common_failure("EmploymentDecisionPhaseMismatch",d.id);terminal=&d;
   }
  }
  Integer through=-1;if(accepted&&!add(accepted->tick,t.service_ticks,through))return common_failure("EstateEmploymentTickOverflow",c.id);
  if(c.acceptance_fact_id!=(accepted?accepted->id:StableId{})||c.accepted_tick!=(accepted?accepted->tick:-1)||c.through_tick!=through||c.terminal_fact_id!=(terminal?terminal->id:StableId{})||c.status!=(terminal?terminal->decision:(accepted?"active":"offered")))return common_failure("EmploymentLifecycleMismatch",c.id);
  if(terminal&&terminal->decision=="expired"&&terminal->tick<(accepted?through:t.offer_expires_tick))return common_failure("EmploymentPrematureExpiry",c.id);
  if(!terminal&&x.state.last_step_tick>=(accepted?through:t.offer_expires_tick))return common_failure("MissingEmploymentExpiry",c.id);
  if(!accepted){if(!c.obligation_id.empty()||(terminal&&!terminal->terminal_arrear_id.empty()))return common_failure("UnexpectedEmploymentWage",c.id);auto reserved=actual_reservation(x.common,c);if(!reserved.ok)return {false,{},reserved.error};if(reserved.value!=(terminal?0:t.reservation_cap))return common_failure("EmploymentReservationMismatch",c.id);continue;}
  if(!serial(x.common,c.obligation_id,"employment_wage")||!obligations.insert(c.obligation_id).second)return common_failure("InvalidEmploymentObligation",c.id);
  auto shop_worker=guard_private_shop_worker_commitment(x.common,x.estate_access?x.estate_access->private_shop_staff:nullptr,t.worker_actor_id,accepted->id,accepted->tick,x.phase);if(!shop_worker.ok)return shop_worker;
  const auto* wage=x.economy.obligations.find(c.obligation_id);if(!wage||wage->id!=c.obligation_id||wage->principal.kind!=SubjectKind::actor||wage->principal.id!=t.employer_actor_id||wage->beneficiary.kind!=SubjectKind::actor||wage->beneficiary.id!=t.worker_actor_id||wage->kind!=ObligationKind::wage||wage->source_wallet_or_inventory!=t.payer_wallet_id||wage->destination!=t.payee_wallet_id||wage->rate_profile!=t.rate_profile||wage->authority_ref!=c.id||wage->period_ticks!=1||wage->next_due_tick!=accepted->tick+1||wage->active||!wage->item_id.empty())return common_failure("EmploymentObligationMismatch",c.id);
  auto& intervals=worker_periods[t.worker_actor_id];const Integer end=terminal?std::min(terminal->tick,through):through;for(const auto& period:intervals)if(accepted->tick<period.second&&period.first<end)return common_failure("OverlappingEmployment",c.id);intervals.emplace_back(accepted->tick,end);
  std::map<StableId,std::pair<Integer,Integer>> dues;std::set<StableId> production_sources;Integer remainder=0,served=0,earned=0;
  for(const auto& actual:x.common.state().facts.rows()){const auto* service=x.state.services.find(actual.first);if(!service||service->contract_id!=c.id)continue;const auto& f=*service;const auto* payload=x.estates.facts.find(f.production_fact_id);const auto* production=payload?std::get_if<EstateProductionFact>(payload):nullptr;
   if(f.id!=actual.first||!header(f.id,"estate_employment_service","estate_employment_service",estate_employment_module)||!production||!header(f.production_fact_id,"estate","estate_production","estate")||!before(accepted->id,f.production_fact_id)||!before(f.production_fact_id,f.id)||!before(f.id,f.arrear_id)||(terminal&&!before(f.id,terminal->id))||f.tick!=production->tick||f.tick<=accepted->tick||f.tick>through||f.tick>x.state.last_step_tick||!service_performed(*production,t)||!production_sources.insert(f.production_fact_id).second||!services.insert(f.id).second||!header(f.arrear_id,"local_due","wage_due","local_economy"))return common_failure("InvalidEmploymentService",f.id);
   Integer due=0,next=0;if(f.remainder_before!=remainder||!ratio(1,t.wage_numerator,t.wage_denominator,remainder,due,next)||f.remainder_after!=next||!add(earned,due,earned)||!add(served,1,served))return common_failure("EmploymentServiceWageMismatch",f.id);remainder=next;dues[f.arrear_id]={f.tick,due};
  }
  // 每次确实到岗都必须且只能计一次，缺服务记录不能被当成没来工作。
  for(const auto& row2:x.estates.facts.rows())if(const auto* production=std::get_if<EstateProductionFact>(&row2.second))if(production->tick>accepted->tick&&production->tick<=through&&production->tick<=x.state.last_step_tick&&before(accepted->id,row2.first)&&(!terminal||before(row2.first,terminal->id))&&service_performed(*production,t)&&!production_sources.count(row2.first))return common_failure("MissingEmploymentService",row2.first);
  if(served>t.service_ticks)return common_failure("EmploymentServiceLimitExceeded",c.id);
  if(terminal){if(remainder){if(!header(terminal->terminal_arrear_id,"local_due","wage_due","local_economy")||!before(terminal->id,terminal->terminal_arrear_id))return common_failure("MissingEmploymentTerminalWage",c.id);dues[terminal->terminal_arrear_id]={terminal->tick,1};if(!add(earned,1,earned))return common_failure("EstateEmploymentWageOverflow",c.id);remainder=0;}else if(!terminal->terminal_arrear_id.empty())return common_failure("UnexpectedEmploymentTerminalWage",c.id);}
  const auto* saved=x.economy.obligation_remainders.find(c.obligation_id);if(!saved||*saved!=remainder||earned>t.reservation_cap)return common_failure("EmploymentRemainderMismatch",c.id);
  Integer paid=0;StableId last;
  for(const auto& event:x.common.state().facts.rows()){
   const auto* debt=x.economy.arrears.find(event.first);if(debt&&debt->obligation_id==c.obligation_id){const auto expected_due=dues.find(event.first);if(expected_due==dues.end()||debt->id!=event.first||debt->due_tick!=expected_due->second.first||debt->original_due!=expected_due->second.second||debt->paid_amount<0||debt->paid_amount>debt->original_due||!all_due.insert(event.first).second)return common_failure("EmploymentArrearMismatch",event.first);last=event.first;}
   const auto* payment=x.economy.payments.find(event.first);if(payment&&payment->obligation_id==c.obligation_id){const auto due=dues.find(payment->arrear_id);if(payment->id!=event.first||!header(event.first,"local_payment","obligation_payment","local_economy")||due==dues.end()||!before(payment->arrear_id,payment->id)||payment->due_tick!=due->second.first||payment->tick<payment->due_tick||payment->tick>observed.value||payment->amount<=0||payment->from_wallet_id!=t.payer_wallet_id||payment->to_wallet_id!=t.payee_wallet_id||payment->authority_ref!=c.id||!add(paid,payment->amount,paid)||!all_payments.insert(payment->id).second)return common_failure("EmploymentPaymentMismatch",event.first);if(x.estate_titles){auto title=x.estate_titles->read_estate_title_before_source(t.estate_id,{"local_economy","obligation_payment",payment->id});if(!title.ok)return {false,{},title.error};if(title.value.wallet_id!=t.payer_wallet_id||!owner_equal(title.value.legal_owner,{Owner::Kind::actor,t.employer_actor_id,{}}))return common_failure("EmploymentPaidTitleSourceMismatch",payment->id);}last=event.first;}
  }
  for(const auto& due:dues){const auto* debt=x.economy.arrears.find(due.first);if(!debt||!all_due.count(due.first))return common_failure("MissingEmploymentArrear",due.first);Integer sum=0;for(const auto& payment:x.economy.payments.rows())if(payment.second.arrear_id==due.first){if(!all_payments.count(payment.first)||!add(sum,payment.second.amount,sum))return common_failure("InvalidEmploymentPayment",payment.first);}if(sum!=debt->paid_amount)return common_failure("EmploymentPaymentSumMismatch",due.first);}
  if(paid>earned||wage->last_receipt_id!=last)return common_failure("EmploymentWageTotalMismatch",c.id);
  auto reserved=actual_reservation(x.common,c);if(!reserved.ok)return {false,{},reserved.error};if(reserved.value!=(terminal?earned-paid:t.reservation_cap-paid))return common_failure("EmploymentReservationMismatch",c.id);
  if(!terminal){const auto* duty=current->duties.find(t.worker_actor_id);if(!has(current->resident_actor_ids,t.worker_actor_id)||!duty||(t.job=="manager"?(current->manager_actor_id!=t.worker_actor_id||*duty!="idle"):(*duty!=t.job||current->manager_actor_id==t.worker_actor_id)))return common_failure("EmploymentEstateDutyMismatch",c.id);}
 }
 // 本合同预约只能出现在冻结付款钱包；伪造另一钱袋/货批的同ID预约不可获得有效归属。
 for(const auto& wallet:x.common.state().wallets.rows())for(const auto& reservation:wallet.second.reserved)if(reservation.action_id.kind==ReservationRef::Kind::contract&&reservation.action_id.id.rfind("estate_employment:",0)==0){const auto* contract=x.state.contracts.find(reservation.action_id.id);if(!contract||wallet.first!=contract->terms.payer_wallet_id)return common_failure("EmploymentReservationContainerMismatch",reservation.action_id.id);}
 for(const auto& inventory:x.common.state().inventories.rows())for(const auto& lot:inventory.second.lots)if(lot.reserved_by.kind==ReservationRef::Kind::contract&&lot.reserved_by.id.rfind("estate_employment:",0)==0)return common_failure("UnexpectedEmploymentGoodsReservation",lot.reserved_by.id);
 if(decisions.size()!=x.state.decisions.size()||services.size()!=x.state.services.size())return common_failure("EmploymentFactRegistryMismatch");
 for(const auto& row:x.economy.obligations.rows())if(row.second.authority_ref.rfind("estate_employment:",0)==0&&!obligations.count(row.first))return common_failure("UnboundEmploymentObligation",row.first);
 for(const auto& row:x.common.state().facts.rows())if(row.second.domain==estate_employment_module&&!x.state.contracts.find(row.first)&&!decisions.count(row.first)&&!services.count(row.first))return common_failure("MissingEmploymentFact",row.first);
 return common_success();
}
// 完整就业准入在原账之外逐原邀约/接受核当时成年；当前已成年不能补写旧约资格。
Status validate_estate_employment(const EstateEmploymentContext& x){
 auto original=validate_estate_employment_original_sources(x);if(!original.ok)return original;
 for(const auto& row:x.state.contracts.rows()){const auto& c=row.second;const auto& t=c.terms;
  for(const auto& actor:{t.employer_actor_id,t.worker_actor_id}){auto age=estate_employment_detail::read_employment_actor_age(x,actor,c.offered_tick,c.id);if(!age.ok)return {false,{},age.error};if(!age.value.adult)return common_failure("EmploymentAdultRequired",actor);}
  for(const auto& row:x.state.decisions.rows()){const auto& d=row.second;if(d.contract_id!=c.id||d.decision!="accept")continue;for(const auto& actor:{t.employer_actor_id,t.worker_actor_id}){auto age=estate_employment_detail::read_employment_actor_age(x,actor,d.tick,d.id);if(!age.ok)return {false,{},age.error};if(!age.value.adult)return common_failure("EmploymentAdultRequired",actor);}}
 }return common_success();
}
}
